\set ON_ERROR_STOP on
begin;
set local request.jwt.claim.role='service_role';
do $test$
declare maker constant uuid:='00000000-0000-4000-8000-000000000151';checker constant uuid:='00000000-0000-4000-8000-000000000152';manager constant uuid:='00000000-0000-4000-8000-000000000153';manager_auth constant uuid:='00000000-0000-4000-8000-000000000154';erp_branch constant uuid:='00000000-0000-4000-8000-000000000155';hq constant uuid:='15000000-0000-4000-8000-000000000001';dealer constant uuid:='25000000-0000-4000-8000-000000000001';branch constant uuid:='35000000-0000-4000-8000-000000000001';account constant uuid:='45000000-0000-4000-8000-000000000001';fee constant uuid:='55000000-0000-4000-8000-000000000001';period_hq constant uuid:='75000000-0000-4000-8000-000000000001';period_branch constant uuid:='75000000-0000-4000-8000-000000000002';clearing constant uuid:='65000000-0000-4000-8000-000000000001';receivable constant uuid:='65000000-0000-4000-8000-000000000002';expense constant uuid:='65000000-0000-4000-8000-000000000003';journal constant uuid:='85000000-0000-4000-8000-000000000001';accrual constant uuid:='95000000-0000-4000-8000-000000000001';open_item constant uuid:='a5000000-0000-4000-8000-000000000001';batch constant uuid:='b5000000-0000-4000-8000-000000000001';batch_item constant uuid:='c5000000-0000-4000-8000-000000000001';invoice constant uuid:='d5000000-0000-4000-8000-000000000001';corr constant uuid:='e5000000-0000-4000-8000-000000000001';result jsonb;replay jsonb;checkout_context jsonb;checkout_result jsonb;
begin
 insert into public.branches(id,code,name,city)values(erp_branch,'CARD-ERP-BRANCH','Sentetik Kart ERP Şubesi','Bursa');
 insert into public.app_users(id,auth_user_id,branch_id,full_name,role,is_active)values(manager,manager_auth,erp_branch,'Sentetik Kart Şube Müdürü','BRANCH_MANAGER',true);
 insert into finance.legal_entities(id,entity_code,legal_name,status,created_by,correlation_id)values(hq,'OTOTR-HQ-CARD-CALLBACK','Sentetik Kart Merkezi','ACTIVE',maker,corr);
 insert into finance.dealer_legal_entities(id,legal_entity_id,dealer_code,legal_name,status,created_by,correlation_id)values(dealer,hq,'CARD-DEALER','Sentetik Kart Bayisi','ACTIVE',maker,corr);
 insert into finance.branches(id,legal_entity_id,dealer_legal_entity_id,branch_code,status,created_by,correlation_id)values(branch,hq,dealer,'CARD-BRANCH','ACTIVE',maker,corr);
 insert into finance.dealer_accounts(id,legal_entity_id,dealer_legal_entity_id,account_code,currency_code,status,created_by,correlation_id)values(account,hq,dealer,'CARD-ACCOUNT','TRY','ACTIVE',maker,corr);
 insert into finance.fee_definitions(id,legal_entity_id,code,version_no,fee_family,name,status,created_by,correlation_id)values(fee,hq,'ROYALTY_CARD',1,'ROYALTY','Royalty Hizmet Bedeli','PUBLISHED',maker,corr);
 insert into finance.finance_periods(id,legal_entity_id,scope_type,period_start,period_end,currency_code,mode,status,created_by,correlation_id)values(period_hq,hq,'HEADQUARTERS',date'2026-11-01',date'2026-11-30','TRY','LIVE','OPEN',maker,corr);
 insert into finance.finance_periods(id,legal_entity_id,parent_period_id,scope_type,dealer_account_id,branch_id,period_start,period_end,currency_code,mode,status,created_by,correlation_id)values(period_branch,hq,period_hq,'BRANCH',account,branch,date'2026-11-01',date'2026-11-30','TRY','LIVE','OPEN',maker,corr);
 insert into finance.operational_accounts(id,legal_entity_id,account_code,account_name,account_type,currency_policy,currency_code,erp_account_code,status,prepared_by,approved_by,approved_at_utc,created_by,correlation_id)values(clearing,hq,'102.KART','Kart Takas','ASSET','FIXED','TRY','102.02','ACTIVE',maker,checker,now(),maker,corr),(receivable,hq,'120.BAYI','Bayi Alacağı','ASSET','FIXED','TRY','120.01','ACTIVE',maker,checker,now(),maker,corr);
 insert into finance.payment_account_mappings(legal_entity_id,payment_method_code,currency_code,version_no,effective_from,clearing_account_id,receivable_account_id,status,prepared_by,approved_by,approved_at_utc,created_by,correlation_id)values(hq,'CREDIT_CARD','TRY',1,date'2026-11-01',clearing,receivable,'ACTIVE',maker,checker,now(),maker,corr);
 insert into finance.pass_through_expenses(id,legal_entity_id,fee_definition_id,supplier_reference,supplier_reference_normalized,contractual_basis_reference,expense_date,currency_code,source_net_amount,source_tax_amount,source_amount,distributable_net_amount,distributable_tax_amount,distributable_amount,allocation_policy,evidence_object_key,evidence_hash,idempotency_key,input_hash,status,prepared_by,approved_by,created_by,correlation_id)values(expense,hq,fee,'CARD-SOURCE','CARD-SOURCE','CARD-BASIS',date'2026-11-03','TRY',100,20,120,100,20,120,'{"method":"SYNTHETIC"}'::jsonb,'synthetic/card.json',repeat('a',64),'card-source',repeat('b',64),'APPROVED',maker,checker,maker,corr);
 insert into finance.journal_entries(id,legal_entity_id,finance_period_id,idempotency_key,intent_hash,entry_type,business_date,posting_date,status,posted_at_utc,posted_by,created_by,correlation_id)values(journal,hq,period_branch,'card-journal',repeat('c',64),'ACCRUAL',date'2026-11-03',date'2026-11-03','POSTED',now(),checker,maker,corr);
 insert into finance.accruals(id,legal_entity_id,pass_through_expense_id,dealer_account_id,branch_id,journal_entry_id,sequence_no,fee_definition_id,currency_code,net_amount,tax_amount,gross_amount,status,created_by,correlation_id)values(accrual,hq,expense,account,branch,journal,1,fee,'TRY',100,20,120,'POSTED',maker,corr);
 insert into finance.open_items(id,legal_entity_id,accrual_id,dealer_account_id,branch_id,due_date,currency_code,item_type,original_amount,allocated_amount,open_amount,status,created_by,correlation_id)values(open_item,hq,accrual,account,branch,date'2026-11-04','TRY','DEBIT',120,0,120,'OPEN',maker,corr);
 insert into finance.billing_batches(id,legal_entity_id,finance_period_id,dealer_account_id,branch_id,idempotency_key,intent_hash,batch_no,grouping_profile_code,currency_code,control_net,control_tax,control_gross,content_hash,status,created_by,correlation_id)values(batch,hq,period_branch,account,branch,'card-batch',repeat('d',64),'CARD-BATCH','ROYALTY-SINGLE-LINE','TRY',100,20,120,repeat('e',64),'INVOICED',maker,corr);
 insert into finance.billing_batch_items(id,billing_batch_id,accrual_id,net_amount,tax_amount,gross_amount,status,created_by,correlation_id)values(batch_item,batch,accrual,100,20,120,'ACTIVE',maker,corr);
 insert into finance.external_invoices(id,legal_entity_id,billing_batch_id,branch_id,idempotency_key,intent_hash,external_system,external_invoice_id,invoice_number,invoice_date,currency_code,net_amount,tax_amount,gross_amount,status,created_by,correlation_id)values(invoice,hq,batch,branch,'card-invoice',repeat('f',64),'SYNTHETIC_CARD','CARD-INV-001','OTOTR-CARD-001',date'2026-11-03','TRY',100,20,120,'ISSUED',maker,corr);
 insert into finance.external_invoice_lines(external_invoice_id,billing_batch_item_id,line_no,net_amount,tax_amount,gross_amount,created_by,correlation_id)values(invoice,batch_item,1,100,20,120,maker,corr);
 insert into finance_private.erp_branch_scope_mappings(erp_branch_id,legal_entity_id,dealer_account_id,finance_branch_id,effective_from,status,created_by,correlation_id)values(erp_branch,hq,account,branch,current_date-1,'ACTIVE',manager,corr);
 checkout_context:=finance_api.prepare_provider_card_checkout(manager_auth,invoice,corr);
 if checkout_context->>'openAmount'<>'120.00000000'or checkout_context->>'paymentMethod'<>'CREDIT_CARD'or checkout_context->>'branchId'<>branch::text then raise exception'checkout context mismatch: %',checkout_context;end if;
 checkout_result:=finance_api.record_provider_card_checkout(manager_auth,invoice,'PROVIDER_TEST',repeat('9',64),120,'TRY',now()+interval'10 minutes',corr);
 if checkout_result->>'outcome'<>'CREATED'or(checkout_result->>'rawCardDataStored')::boolean or(checkout_result->>'providerTokenStored')::boolean then raise exception'checkout record mismatch: %',checkout_result;end if;
 replay:=finance_api.record_provider_card_checkout(manager_auth,invoice,'PROVIDER_TEST',repeat('9',64),120,'TRY',now()+interval'10 minutes',corr);
 if replay->>'outcome'<>'REPLAY'or replay->>'checkoutSessionId'<>checkout_result->>'checkoutSessionId'then raise exception'checkout replay mismatch: %',replay;end if;
 if exists(select 1 from finance.outbox_messages where event_type='PROVIDER_CARD_CHECKOUT_CREATED'and(payload::text~'411111|cvv|cardNumber'))then raise exception'raw card data leaked to checkout outbox';end if;
 perform finance_api.evaluate_branch_operation_access(checker,hq,account,branch,date'2026-11-05',corr);
 result:=finance_api.commit_provider_card_payment_callback(maker,checker,invoice,'PROVIDER_TEST','event:card:000001','payment:card:000001','2026-11-05T09:00:00+03'::timestamptz,120,'TRY',repeat('1',64),corr);
 if result->>'outcome'<>'SETTLED'or result->>'paymentStatus'<>'ALLOCATED'or result->>'accessState'<>'OPEN'or(result->>'rawCardDataStored')::boolean then raise exception'callback settlement mismatch: %',result;end if;
 if(select open_amount from finance.open_items where id=open_item)<>0 or(select status from finance.open_items where id=open_item)<>'CLOSED'then raise exception'invoice open item not closed';end if;
 if(select count(*)from finance.payments where status='ALLOCATED'and received_amount=120 and verified_amount=120 and allocated_amount=120)<>1 then raise exception'allocated verified payment missing';end if;
 if exists(select 1 from finance.journal_entries je where je.entry_type='PAYMENT_VERIFICATION'and(select coalesce(sum(debit_amount),0)<>coalesce(sum(credit_amount),0)from finance.journal_lines where journal_entry_id=je.id))then raise exception'unbalanced payment journal';end if;
 replay:=finance_api.commit_provider_card_payment_callback(maker,checker,invoice,'PROVIDER_TEST','event:card:000001','payment:card:000001','2026-11-05T09:00:00+03'::timestamptz,120,'TRY',repeat('1',64),corr);if replay->>'outcome'<>'REPLAY'or replay->>'accessState'<>'OPEN'then raise exception'callback replay mismatch: %',replay;end if;
 if(select count(*)from finance.payments)<>1 or(select count(*)from finance.payment_allocations where status='ACTIVE')<>1 then raise exception'callback replay duplicated financial records';end if;
 raise notice'PROVIDER CARD CHECKOUT + CALLBACK E2E PASSED: scoped token-hash checkout and signed settlement can unlock without raw card data';
end$test$;
rollback;
